.menurail__top { display: flex; flex-wrap: wrap; align-items: center; gap: var(--space-2); min-width: 0px; }
.menurail__mark { display: inline-flex; flex: 0 0 auto; }
.menurail__title { flex: 1 1 var(--menurail-title-min); min-width: 0px; overflow: hidden; font-family: var(--font-display); font-size: var(--fs-title-md); font-weight: var(--w-bold); line-height: var(--lh-tight); text-overflow: ellipsis; white-space: nowrap; }
.menurail__meta { flex: 0 0 auto; font-family: var(--font-mono); font-size: var(--fs-small); font-weight: var(--w-bold); font-variant-numeric: tabular-nums; }
.menurail__fold { display: grid; grid-template-rows: 1fr; }
