.menurail__panel { display: grid; grid-template-rows: 0fr; }
.menurail__panelin { min-height: 0px; overflow: hidden; visibility: hidden; }
.menurail__inner { padding: var(--space-3h) var(--space-1) var(--space-1) 0; }
.menurail__back.btn { margin-bottom: var(--space-3); }
.menurail__card.btn { transition: flex-basis var(--dur-unfold) var(--ease-unfold),
    padding var(--dur-unfold) var(--ease-unfold),
    background-color var(--dur-med) var(--ease-standard),
    border-color var(--dur-fast) var(--ease-standard),
    box-shadow var(--dur-fast) var(--ease-stamp),
    transform var(--dur-fast) var(--ease-stamp); }
.menurail__fold { transition: grid-template-rows var(--dur-unfold) var(--ease-unfold); }
.menurail__panel { transition: grid-template-rows var(--dur-unfold) var(--ease-unfold); }
.menurail__panelin { transition: visibility 0s var(--dur-unfold); }
@media (prefers-reduced-motion: reduce) {
.menurail__card.btn { transition: none; }
.menurail__fold { transition: none; }
.menurail__panel { transition: none; }
.menurail__panelin { transition: none; }
}
.pnext__page { padding-top: var(--space-4); }
.pnext__section { padding-top: var(--space-3h); }
.playernext .pnext__section { flex-flow: wrap; container-type: inline-size; }
.pnext__section > .pnext__slot { flex: 1 1 100%; min-width: 0px; }
.pnext__slot { margin-top: var(--space-3h); }
.pnext-pick { min-height: var(--space-12); padding: 0 var(--space-3h); border: var(--bw-heavy) solid var(--border-stamped); border-radius: 0px; background: var(--surface-card); color: var(--text-heading); font-family: var(--font-display); font-size: var(--fs-body); font-weight: var(--w-bold); letter-spacing: var(--ls-caps); line-height: var(--lh-solid); text-transform: uppercase; cursor: pointer; }
.pnext-pick:disabled { opacity: var(--opacity-disabled); cursor: default; }
.pnext-pick[aria-pressed="true"] { background: var(--text-body); color: var(--text-on-ink); }
.pnext-pick:focus-visible { outline: var(--bw-heavy) solid var(--focus-ring); outline-offset: var(--bw-heavy); }
.arsenal { display: grid; gap: var(--space-6); }
@media (min-width: 740px) {
.arsenal { grid-template-columns: repeat(2, minmax(0px, 1fr)); align-items: start; }
}
.arsenal__card, .flight { display: flex; flex-direction: column; gap: var(--space-3); min-width: 0px; }
.arsenal__glyph { fill: var(--pitch, var(--text-caption)); stroke: var(--text-heading); stroke-width: 1.4; stroke-linejoin: round; }
.arsenal__glyph--ring { fill: none; stroke: var(--pitch, var(--text-caption)); stroke-width: 3; }
.arsenal__icon { flex: 0 0 auto; }
.arsenal__mix { display: flex; height: var(--space-10); border: var(--bw-heavy) solid var(--border-stamped); clip-path: inset(calc(var(--space-2) * -1) calc((1 - var(--roll, 1)) * 100%) calc(var(--space-2) * -1) 0); }
.arsenal__seg { display: flex; flex: 1 1 0px; flex-direction: column; align-items: center; justify-content: center; position: relative; min-width: 0px; overflow: hidden; border-right: var(--bw-heavy) solid var(--border-stamped); background: var(--pitch, var(--text-caption)); color: var(--text-heading); font-family: var(--font-display); font-size: var(--fs-label); line-height: var(--lh-solid); }
.arsenal__seg:last-child { border-right: 0px; }
.arsenal__seg--ring { background: var(--surface-card); box-shadow: inset 0 0 0 var(--space-1) var(--pitch, var(--text-caption)); }
.arsenal__seg span { font-family: var(--font-mono); font-weight: var(--w-bold); }
.arsenal__mixwrap { position: relative; }
.arsenal__seg > b, .arsenal__seg > span { position: relative; }
.arsenal__flash { position: absolute; inset: 0px; background: var(--surface-card); pointer-events: none; }
.arsenal__rolledge { position: absolute; top: 0px; bottom: 0px; left: calc(var(--roll, 1) * 100%); width: var(--space-3); margin-left: calc(var(--space-3) * -1); background: linear-gradient(90deg, transparent, color-mix(in srgb, var(--text-heading) 30%, transparent)); pointer-events: none; }
.arsenal__sweep { position: absolute; inset: 0px; z-index: -1; transform-origin: left center; background: color-mix(in srgb, var(--accent-tint) 50%, transparent); pointer-events: none; }
.arsenal__pop { display: inline-flex; }
.arsenal__side, .flight__stage { position: relative; border: var(--bw-heavy) solid var(--border-stamped); background: var(--surface-card); line-height: var(--lh-zero); }
.flight__canvas { display: block; width: 100%; height: auto; aspect-ratio: 336 / 300; }
.flight__turn { cursor: grab; touch-action: pan-y; user-select: none; }
.flight__turn:focus-visible { outline: var(--bw-heavy) solid var(--focus-ring); outline-offset: var(--bw-heavy); }
.flight__hint { margin-left: auto; color: var(--text-caption); font-family: var(--font-display); font-size: var(--fs-label); letter-spacing: var(--ls-xwide); }
@media (max-width: 439px) {
