}
.arsenal__scene { display: block; width: 100%; height: auto; }
.arsenal__ground { fill: none; stroke: var(--border-grid); stroke-width: 1; }
.arsenal__ground--mound { stroke: var(--text-caption); }
.arsenal__rubber { fill: var(--text-heading); }
.arsenal__plate { fill: var(--text-caption); }
.arsenal__zone { fill: var(--surface-inset); stroke: var(--text-heading); stroke-width: 1.6; }
.arsenal__halo { fill: none; stroke: var(--text-heading); stroke-width: 4.6; stroke-linejoin: round; }
.arsenal__trail { fill: none; stroke: var(--pitch, var(--text-caption)); stroke-width: 2.4; stroke-linejoin: round; }
.arsenal__tick { fill: none; stroke: var(--text-heading); stroke-width: 1.4; stroke-dasharray: 1; }
.arsenal__ticklabel { fill: var(--text-caption); font-family: var(--font-mono); }
.arsenal__inset { position: absolute; top: var(--space-1); right: var(--space-1); width: 24%; min-width: calc(var(--space-16) * 1.25); border: var(--bw-rule) solid var(--border-stamped); background: var(--surface-card); }
.arsenal__inset text { fill: var(--text-caption); font-family: var(--font-mono); }
.arsenal__zonebox { fill: none; stroke: var(--text-heading); stroke-width: 1.4; }
.arsenal__bar, .flight__bar, .flight__row { display: flex; flex-wrap: wrap; align-items: center; gap: var(--space-2); }
.arsenal__range { flex: 1 1 9rem; min-width: 0px; height: var(--tap-min); margin: 0px; accent-color: var(--text-heading); cursor: ew-resize; }
.arsenal__figs { color: var(--text-muted); font-family: var(--font-mono); font-size: var(--fs-cell); }
.arsenal__spark { width: 100%; height: var(--space-6); overflow: visible; }
.arsenal__sparkline { fill: none; stroke: var(--text-heading); stroke-width: 3; stroke-linejoin: round; vector-effect: non-scaling-stroke; }
.flight__label { display: flex; align-items: baseline; justify-content: space-between; gap: var(--space-3); padding-bottom: var(--space-1); border-bottom: var(--bw-heavy) solid var(--border-stamped); }
.flight__label b { white-space: nowrap; color: var(--text-caption); font-family: var(--font-display); font-size: var(--fs-label); letter-spacing: var(--ls-xwide); }
.flight__label em { font-family: var(--font-mono); font-size: var(--fs-label); font-style: normal; text-align: right; }
.flight__range { flex: 1 1 9rem; min-width: 0px; height: var(--space-10); margin: 0px; accent-color: var(--text-heading); }
.flight__clock { min-width: 5ch; color: var(--text-caption); font-family: var(--font-mono); font-size: var(--fs-label); text-align: right; }
.flight__ask { margin: 0 0 var(--space-2); color: var(--text-heading); font-family: var(--font-display); font-size: var(--fs-title-md); font-weight: var(--w-bold); line-height: var(--lh-solid); }
.flight__note { margin: 0 0 var(--space-2); color: var(--text-caption); font-family: var(--font-mono); font-size: var(--fs-cell); line-height: var(--lh-loose); }
.flight__facts { display: grid; grid-template-columns: repeat(auto-fit, minmax(14rem, 1fr)); gap: 0 var(--space-5); }
