.flight__fact b { display: block; color: var(--text-caption); font-family: var(--font-display); font-size: var(--fs-label); letter-spacing: var(--ls-xwide); }
.flight__fact em { font-family: var(--font-mono); font-size: var(--fs-num-lg); font-style: normal; font-weight: var(--w-bold); }
.flight__fact small { display: block; color: var(--text-caption); font-family: var(--font-mono); font-size: var(--fs-cell); line-height: var(--lh-loose); }
@media (hover: hover) {
.logtable__grid tbody tr:not(.logtable__div, :has(a, button)):hover { background: var(--surface-row-hover); }
}
